func pipeline(jobs []Job) {
 results := make(chan Result, 1)
 var wg sync.WaitGroup
 for _, job := range jobs {
  wg.Add(1)
  go func(j Job) { defer wg.Done(); results <- work(j) }(job)
 }
 wg.Wait()
 close(results)
 for result := range results { save(result) }
}

